private void checkStoragePermissionAndFileGet() {
  Context context = getContext();
  if (!MainActivity.hasPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE, context)) {
    if (storagePermissionRefusedOnce) {
      showStoragePermissionRefusedError();
      restoreMainActionButton();
      return;
    }
    fileGetPending = true;
    MainActivity.requestPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE, MainActivity.REQUEST_STORAGE_PERMISSION, getString(R.string.storage_permission_rationale_download), context, true);
  } else {
    try {
      fileGet(true);
    } catch (NullPointerException | IllegalFormatException | SecurityException e) {
      // Handle the exception, e.g., log the error or show a user-friendly message
      e.printStackTrace();
    }
  }
}
